1	/**
2	 * Feature Flags — stored in Supabase system_config table.
3	 *
4	 * Run in Supabase SQL editor to create the table:
5	 *
6	 * CREATE TABLE IF NOT EXISTS system_config (
7	 *   key TEXT PRIMARY KEY,
8	 *   value JSONB NOT NULL DEFAULT '{}',
9	 *   updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
10	 * );
11	 * ALTER TABLE system_config ENABLE ROW LEVEL SECURITY;
12	 * CREATE POLICY "Admins can manage system_config" ON system_config
13	 *   FOR ALL USING (
14	 *     EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'super_admin'))
15	 *   );
16	 */
17	
18	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
19	import supabase from "@/lib/supabase";
20	import { toast } from "sonner";
21	
22	export interface FlagDefinition {
23	  key: string;
24	  label: string;
25	  description: string;
26	  defaultValue: boolean;
27	  category: "ui" | "feature" | "system";
28	  requiresSuperAdmin?: boolean;
29	}
30	
31	export const FLAG_DEFINITIONS: FlagDefinition[] = [
32	  {
33	    key: "agent_hub_enabled",
34	    label: "AI Agent Hub",
35	    description: "Show the AI Agent Hub section in the user sidebar navigation.",
36	    defaultValue: true,
37	    category: "ui",
38	  },
39	  {
40	    key: "integrations_enabled",
41	    label: "Integrations Page",
42	    description:
43	      "Show the Integrations page (Hotjar, GA4, Clarity, Search Console) in user navigation.",
44	    defaultValue: true,
45	    category: "ui",
46	  },
47	  {
48	    key: "pdf_export_enabled",
49	    label: "PDF Export",
50	    description:
51	      "Allow users to download audit reports as PDF. Requires a PDF generation service.",
52	    defaultValue: false,
53	    category: "feature",
54	  },
55	  {
56	    key: "email_notifications_enabled",
57	    label: "Email Notifications",
58	    description:
59	      "Send email alerts when scan completes, plan changes, or usage limit is reached.",
60	    defaultValue: false,
61	    category: "feature",
62	  },
63	  {
64	    key: "free_scan_enabled",
65	    label: "Public Scan (No Auth)",
66	    description:
67	      "Allow anonymous users to run a scan without signing in. Uses rate limiting.",
68	    defaultValue: true,
69	    category: "feature",
70	  },
71	  {
72	    key: "maintenance_mode",
73	    label: "Maintenance Mode",
74	    description:
75	      "Show a maintenance banner to all users. Does not block access — visual notice only.",
76	    defaultValue: false,
77	    category: "system",
78	    requiresSuperAdmin: true,
79	  },
80	];
81	
82	const DEFAULT_FLAGS: Record<string, boolean> = Object.fromEntries(
83	  FLAG_DEFINITIONS.map((f) => [f.key, f.defaultValue])
84	);
85	
86	export interface FeatureFlagsData {
87	  flags: Record<string, boolean>;
88	  updatedAt: string | null;
89	}
90	
91	async function fetchFeatureFlags(): Promise<FeatureFlagsData> {
92	  const { data, error } = await supabase
93	    .from("system_config")
94	    .select("value, updated_at")
95	    .eq("key", "feature_flags")
96	    .single();
97	
98	  if (error && error.code !== "PGRST116") {
99	    // PGRST116 = row not found — that's fine, we use defaults
100	    throw new Error(error.message);
101	  }
102	
103	  const stored = (data?.value ?? {}) as Record<string, boolean>;
104	
105	  // Merge stored values with defaults (stored values take priority)
106	  const flags: Record<string, boolean> = { ...DEFAULT_FLAGS, ...stored };
107	
108	  return {
109	    flags,
110	    updatedAt: data?.updated_at ?? null,
111	  };
112	}
113	
114	// ── Admin hook: reads + writes ────────────────────────────────
115	
116	export function useFeatureFlags() {
117	  return useQuery({
118	    queryKey: ["admin", "feature-flags"],
119	    queryFn: fetchFeatureFlags,
120	    staleTime: 60_000,
121	  });
122	}
123	
124	export function useUpdateFeatureFlag() {
125	  const queryClient = useQueryClient();
126	
127	  return useMutation({
128	    mutationFn: async ({
129	      key,
130	      enabled,
131	      currentFlags,
132	    }: {
133	      key: string;
134	      enabled: boolean;
135	      currentFlags: Record<string, boolean>;
136	    }) => {
137	      const mergedFlags = { ...currentFlags, [key]: enabled };
138	
139	      const { error } = await supabase.from("system_config").upsert(
140	        {
141	          key: "feature_flags",
142	          value: mergedFlags,
143	          updated_at: new Date().toISOString(),
144	        },
145	        { onConflict: "key" }
146	      );
147	
148	      if (error) throw new Error(error.message);
149	
150	      return { key, enabled, mergedFlags };
151	    },
152	    onSuccess: (result) => {
153	      const flagDef = FLAG_DEFINITIONS.find((f) => f.key === result.key);
154	      const label = flagDef?.label ?? result.key;
155	      toast.success(`${label} ${result.enabled ? "enabled" : "disabled"}`);
156	      // Invalidate both admin and app-level queries
157	      queryClient.invalidateQueries({ queryKey: ["admin", "feature-flags"] });
158	      queryClient.invalidateQueries({ queryKey: ["feature-flags"] });
159	    },
160	    onError: (error: Error) => {
161	      toast.error(`Failed to update flag: ${error.message}`);
162	    },
163	  });
164	}
